INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_7c4790372dc83181168fb6e7','wiki/sources/trassenanmeldung-im-gelegenheitsverkehr.md',0,'Inhalt','Bei Anmeldungen zum Gelegenheitsverkehr handelt es sich um:

- Anmeldungen außerhalb des Netzfahrplans bzw. außerhalb der Fristen des Netzfahrplans
- Änderungsanmeldungen zu Trassen des Netzfahrplans
- Änderungsanmeldungen zu Trassen des Gelegenheitsverkehrs

Trassen für den Gelegenheitsverkehr werden im Rahmen der vorhandenen freien Kapazitäten der Infrastruktur konstruiert.

Um eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben in der Trassenanmeldung wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtverlauf.

Die DB InfraGO AG stellt für die Trassenanmeldung das **Trassenportal Netz (TPN)** zur Verfügung, das über eine Schnittstelle an interne IT-Systeme angebunden und auch aus dem Internet zugänglich ist. Die Nutzung des elektronischen Datenaustauschs ist zwischen der DB InfraGO AG und den Zugangsberechtigten zu vereinbaren.

Trassenanmeldungen und alle zugehörigen Folgeaufträge müssen über TPN erfolgen. Fragen rund um TPN beantworten Ihnen gerne unsere Ansprechpartner:innen in den Regionen. Weitere Informationen finden Sie auch [hier](https://preview-ecm.intranet.deutschebahn.com/blueprint/servlet/infra/schienennetz/leistungen/trassen/Trassenbestellung/Trassenanmeldung/trassenportal_netz-11249618 "Wird in einem neuen Tab geöffnet") im Internet. Im Fall des technischen Ausfalls bzw. im Fall von Übertragungsstörungen des Systems TPN oder im Fall eines nicht verfügbaren IT-Systems beim Antragsteller können Trassenanmeldungen per E-Mail oder Fax unter Verwendung des jeweils gültigen Anmeldeformulars erfolgen.',191,'{"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/gelegenheitsverkehr-10907274","normalized_sha256":"1f4ac919ba695429e938615de28752003e54d04b09802cfdd71f8cd019811c9d","page":null,"source_id":"src_a84dc841278f39fe70cc","source_sha256":"e50d6d625061099073b4a3ed0a0f661a658aac0ab369daaeadca08b09775c4a7","source_version_id":"sv_778cf7ecc04d4171056d4583"}','5690a2e4bd848fd596d4c8c7f93c3a2b1b08c993184945c6865e49857579eee1');
--> statement-breakpoint
INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_7a8af2bce3efe1fc8750be8e','wiki/sources/trassenanmeldung-im-gelegenheitsverkehr.md',1,'Inhalt','Die für diesen Fall verbindlichen Anmeldeformulare und Leitfäden stehen nachfolgend zum Download zur Verfügung. Mündliche oder fernmündliche Trassenanmeldungen sind in allen Fällen ausgeschlossen.

Folgende Anmeldeformulare und Leitfäden für die Trassenanmeldung im Gelegenheitsverkehr stehen zum Download zur Verfügung:

- Erläuterungen zu den Trassenanmeldungen finden Sie in der (Richtlinie 402.0202)
- Leitfaden für die **Trassenanmeldung Gelegenheitsverkehr** (Ril 402.0202A02)
- Leitfaden für die **Trassenanmeldung Netzfahrplan** (Ril 402.0202A01)
- Leitfaden für **Trassenanmeldung Baufahrzeuge / Nebenfahrzeuge** (Ril 402.0202A03)
- Leitfaden für die **Bremsstellung von Zügen** (Ril 402.0202A04)
- **Vordruck Anmeldung zum Gelegenheitsverkehr** (Ril 402.0202V02)
- **Vordruck Anmeldung zum Netzfahrplan** (Ril 402.0202V01)
- **Vordruck Anmeldung von Baumaschinen und sonstigen Nebenfahrzeugen** (Ril 402.0202V03)
- **Vordruck Anmeldung von außergewöhnlichen Transporten mit Bza-Nr.** (Ril 402.0202V04)
- **Vordruck Anforderungsprofil für Fahrdynamische Triebfahrzeugdaten** (Ril 402.0202V05)

Sie finden die Downloads auf der Seite [*Anmeldeformulare*](https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/formulare-10907276).',132,'{"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/gelegenheitsverkehr-10907274","normalized_sha256":"1f4ac919ba695429e938615de28752003e54d04b09802cfdd71f8cd019811c9d","page":null,"source_id":"src_a84dc841278f39fe70cc","source_sha256":"e50d6d625061099073b4a3ed0a0f661a658aac0ab369daaeadca08b09775c4a7","source_version_id":"sv_778cf7ecc04d4171056d4583"}','e20bcea054348eb86c0f4c58192326565435df65d6016ef3acc8b9daee4b73e1');
