INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_e820dee74632576c0eb649bc','wiki/sources/trassenanmeldung-im-netzfahrplan.md',0,'Inhalt','Die DB InfraGO AG konstruiert die Trassen des Netzfahrplans auf der Basis von Trassenanmeldungen. Um eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtverlauf.

Die jeweilige Trassenanmeldefristen für die Netzfahrpläne sind in Ziffer 4.2 der Infrastrukturnutzungsbedingungen (INB) genannt.

Die DB InfraGO AG stellt für die Trassenanmeldung das Trassenanmeldesystem pathOS zur Verfügung, das über eine Schnittstelle an interne IT-Systeme angebunden und auch aus dem Internet zugänglich ist. Die Nutzung des elektronischen Datenaustauschs ist zwischen der DB InfraGO AG und den Zugangsberechtigten zu vereinbaren.

Trassenanmeldungen und im Rahmen der Zuweisung erforderliche Angaben bzw. Handlungen im Netzfahrplan i. S. d. der INB müssen über pathOS erfolgen. Insbesondere im Fall des technischen Ausfalls bzw. im Fall von Übertragungsstörungen des Systems oder im Fall eines nicht verfügbaren IT-Systems beim Antragsteller können Trassenanmeldungen per E-Mail unter Verwendung des jeweils gültigen Anmeldeformulars erfolgen.

Die für diesen Fall verbindlichen Anmeldeformulare und Leitfäden stehen nachfolgend zum Download zur Verfügung. Mündliche oder fernmündliche Trassenanmeldungen sind in allen Fällen ausgeschlossen.

Folgende Anmeldeformulare und Leitfäden stehen für die Trassenanmeldung im Netzfahrplan zum Download zur Verfügung:',191,'{"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/netzfahrplan-11861526","normalized_sha256":"f9cac652f176673dedf0f4e6f85f4b0cd2a1c35ba85d27e97c4fb6efb4025caf","page":null,"source_id":"src_55f3c19c14f539666c5f","source_sha256":"2bbb0a1d9156b3b52057c4c9a5227ea83b4180ae65010634fe7333260185819c","source_version_id":"sv_5d5a297063e24f3830a5c3dc"}','b2a0807744ed3991964664f2581c77db0a6f081c8e5de1f5abd4119c8f7d0a2a');
